WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Parkiet','Perruche','Budgerigar','parkiet','parkiet',12,9,'Leer hoe je een parkiet in een Brussels appartement gezond en gelukkig houdt.','Découvrez comment garder une perruche en bonne santé et heureuse dans un appartement bruxellois.','Learn how to keep a budgie healthy and happy in a Brussels apartment.','vogels',40)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Wat is de minimale grootte voor een parkietenkooi voor twee vogels?','Quelle est la taille minimale d''une cage à perruches pour deux oiseaux ?','What is the minimum cage size for two budgerigars?','["30x30x30 cm", "80x40x50 cm of groter", "20x20x20 cm", "De grootte maakt niet uit"]'::jsonb,'["30x30x30 cm", "80x40x50 cm ou plus grand", "20x20x20 cm", "La taille n''a pas d''importance"]'::jsonb,'["30x30x30 cm", "80x40x50 cm or larger", "20x20x20 cm", "Size doesn''t matter"]'::jsonb,1,'Parkieten moeten kunnen vliegen in hun kooi; een kleine kooi leidt tot stress en gedragsproblemen.','Les perruches doivent pouvoir voler dans leur cage ; une cage trop petite cause stress et troubles du comportement.','Budgies need room to fly inside their cage; a small cage causes stress and behavioural problems.'),
  (1,'tekst','Waarom zijn zitstokken van verschillende diktes belangrijk?','Pourquoi des perchoirs de diamètres différents sont-ils importants ?','Why are perches of different diameters important?','["Voor de decoratie", "Om voetproblemen te voorkomen", "Ze zijn niet belangrijk", "Om lawaai te maken"]'::jsonb,'["Pour la décoration", "Pour prévenir les problèmes de pattes", "Ils ne sont pas importants", "Pour faire du bruit"]'::jsonb,'["For decoration", "To prevent foot problems", "They are not important", "To make noise"]'::jsonb,1,'Variatie in stokdikte traint de voetspieren en voorkomt drukplekken en bevangenheid.','La variété de diamètre entraîne les muscles des pattes et évite les points de pression.','Varied perch thickness exercises foot muscles and prevents pressure sores.'),
  (1,'tekst','Hoeveel uur natuurlijk daglicht of volledig spectrum licht heeft een parkiet ongeveer nodig?','De combien d''heures de lumière naturelle une perruche a-t-elle besoin ?','How many hours of natural or full-spectrum light does a budgie need?','["2-4 uur", "10-12 uur", "24 uur ononderbroken", "Licht is niet nodig"]'::jsonb,'["2-4 heures", "10-12 heures", "24 heures sans interruption", "La lumière n''est pas nécessaire"]'::jsonb,'["2-4 hours", "10-12 hours", "24 hours non-stop", "Light is not necessary"]'::jsonb,1,'Een regelmatig dag-nachtritme met voldoende licht is essentieel voor hormonen en welzijn.','Un rythme jour-nuit régulier avec suffisamment de lumière est essentiel pour les hormones et le bien-être.','A regular day-night cycle with enough light is essential for hormones and wellbeing.'),
  (1,'tekst','Waar moet je een parkietenkooi in een Brussels appartement best niet plaatsen?','Où ne faut-il surtout pas placer une cage à perruches dans un appartement bruxellois ?','Where should you avoid placing a budgie cage in a Brussels apartment?','["In een rustige hoek", "Vlak bij het keukenraam", "Vlak naast de kookplaat", "Op ooghoogte"]'::jsonb,'["Dans un coin calme", "Près de la fenêtre de cuisine", "Juste à côté de la plaque de cuisson", "À hauteur des yeux"]'::jsonb,'["In a quiet corner", "Near a kitchen window", "Right next to the stove", "At eye level"]'::jsonb,2,'Dampen van anti-aanbakpannen (PTFE) zijn zeer giftig voor vogels en kunnen dodelijk zijn.','Les vapeurs de poêles antiadhésives (PTFE) sont très toxiques pour les oiseaux et peuvent être mortelles.','Fumes from non-stick pans (PTFE) are highly toxic to birds and can be fatal.'),
  (2,'tekst','Wat is het probleem met een dieet dat enkel uit zaadjes bestaat?','Quel est le problème d''une alimentation composée uniquement de graines ?','What is the problem with a seed-only diet?','["Er is geen probleem", "Het veroorzaakt tekorten aan vitamines en vet zwaarlijvigheid", "Het is te duur", "Zaadjes zijn giftig"]'::jsonb,'["Il n''y a pas de problème", "Cela cause des carences en vitamines et de l''obésité", "C''est trop cher", "Les graines sont toxiques"]'::jsonb,'["There is no problem", "It causes vitamin deficiencies and obesity", "It''s too expensive", "Seeds are toxic"]'::jsonb,1,'Een uitsluitend zaaddieet is vetrijk en arm aan vitamine A, wat leidt tot gezondheidsproblemen.','Une alimentation exclusivement à base de graines est riche en graisses et pauvre en vitamine A, causant des problèmes de santé.','A seed-only diet is high in fat and low in vitamin A, leading to health problems.'),
  (2,'tekst','Welk voedsel is giftig voor parkieten?','Quel aliment est toxique pour les perruches ?','Which food is toxic to budgies?','["Broccoli", "Avocado", "Appel zonder pitjes", "Gekookte wortel"]'::jsonb,'["Le brocoli", "L''avocat", "La pomme sans pépins", "La carotte cuite"]'::jsonb,'["Broccoli", "Avocado", "Apple without seeds", "Cooked carrot"]'::jsonb,1,'Avocado bevat persine, een stof die bij vogels hartproblemen en de dood kan veroorzaken.','L''avocat contient de la persine, une substance qui peut causer des problèmes cardiaques et la mort chez les oiseaux.','Avocado contains persin, a substance that can cause heart problems and death in birds.'),
  (2,'tekst','Hoe vaak moet je vers water en voedsel verversen?','À quelle fréquence faut-il renouveler l''eau et la nourriture fraîches ?','How often should fresh water and food be refreshed?','["Dagelijks", "Om de week", "Om de maand", "Nooit nodig"]'::jsonb,'["Chaque jour", "Une fois par semaine", "Une fois par mois", "Jamais nécessaire"]'::jsonb,'["Daily", "Weekly", "Monthly", "Never needed"]'::jsonb,0,'Dagelijks vers water en voer voorkomt bacteriegroei en houdt de vogel gezond.','De l''eau et de la nourriture fraîches chaque jour évitent la prolifération bactérienne et maintiennent l''oiseau en bonne santé.','Fresh water and food daily prevent bacterial growth and keep the bird healthy.'),
  (2,'tekst','Wat is een teken van ziekte bij een parkiet?','Quel est un signe de maladie chez une perruche ?','What is a sign of illness in a budgie?','["Actief kwetteren", "Opgezette veren en lusteloosheid", "Veel eten", "Regelmatig baden"]'::jsonb,'["Gazouillis actif", "Plumes ébouriffées et léthargie", "Manger beaucoup", "Se baigner régulièrement"]'::jsonb,'["Active chirping", "Fluffed feathers and lethargy", "Eating a lot", "Bathing regularly"]'::jsonb,1,'Vogels verbergen ziekte instinctief; opgezette veren en stilte kunnen wijzen op ernstige problemen.','Les oiseaux cachent instinctivement leur maladie ; des plumes ébouriffées et le silence peuvent indiquer un problème grave.','Birds instinctively hide illness; fluffed feathers and silence can signal serious problems.'),
  (3,'tekst','Hoe herken je stress bij een parkiet?','Comment reconnaît-on le stress chez une perruche ?','How can you recognize stress in a budgie?','["Ze zingt luid", "Veren plukken of bijten", "Ze slaapt overdag", "Ze eet meer dan normaal"]'::jsonb,'["Elle chante fort", "S''arracher les plumes ou mordre", "Elle dort la journée", "Elle mange plus que d''habitude"]'::jsonb,'["It sings loudly", "Feather plucking or biting", "It sleeps during the day", "It eats more than usual"]'::jsonb,1,'Verenplukken is vaak een teken van stress, verveling of een te kleine leefruimte.','L''arrachage de plumes est souvent un signe de stress, d''ennui ou d''un espace de vie trop petit.','Feather plucking is often a sign of stress, boredom, or too small a living space.'),
  (3,'tekst','Waarom hebben parkieten best gezelschap van een soortgenoot?','Pourquoi les perruches ont-elles besoin de la compagnie d''un congénère ?','Why do budgies benefit from having a companion of their own kind?','["Om te vechten", "Het zijn sociale dieren die eenzaamheid slecht verdragen", "Het is niet nodig", "Om meer te eten"]'::jsonb,'["Pour se battre", "Ce sont des animaux sociaux qui supportent mal la solitude", "Ce n''est pas nécessaire", "Pour manger davantage"]'::jsonb,'["To fight", "They are social animals that cope poorly with loneliness", "It''s not necessary", "To eat more"]'::jsonb,1,'Parkieten leven in het wild in groepen; alleen gehouden vogels hebben veel menselijke aandacht nodig.','Dans la nature, les perruches vivent en groupe ; seules, elles ont besoin de beaucoup d''attention humaine.','In the wild budgies live in flocks; kept alone they need a lot of human attention.'),
  (3,'tekst','Hoe train je een parkiet om op je hand te komen zitten?','Comment entraîner une perruche à venir se poser sur la main ?','How do you train a budgie to step onto your hand?','["Door de kooi te schudden", "Met geduld en beloningen zoals millet", "Door de vogel vast te grijpen", "Door te schreeuwen"]'::jsonb,'["En secouant la cage", "Avec patience et récompenses comme le millet", "En attrapant l''oiseau", "En criant"]'::jsonb,'["By shaking the cage", "With patience and rewards like millet", "By grabbing the bird", "By shouting"]'::jsonb,1,'Positieve training met kleine beloningen bouwt vertrouwen op zonder de vogel te stressen.','Un entraînement positif avec de petites récompenses instaure la confiance sans stresser l''oiseau.','Positive training with small rewards builds trust without stressing the bird.'),
  (3,'tekst','Wat moet je doen als je parkiet vrij rondvliegt in de kamer?','Que faut-il faire si votre perruche vole librement dans la pièce ?','What should you do if your budgie flies freely around the room?','["Ramen en spiegels afdekken", "Alle deuren wijd openzetten", "Niets, het is veilig", "De kat erbij laten"]'::jsonb,'["Couvrir fenêtres et miroirs", "Ouvrir grand toutes les portes", "Rien, c''est sans danger", "Laisser le chat s''approcher"]'::jsonb,'["Cover windows and mirrors", "Open all doors wide", "Nothing, it''s safe", "Let the cat come near"]'::jsonb,0,'Vogels herkennen glas niet en kunnen zich ernstig verwonden tegen ramen of spiegels.','Les oiseaux ne reconnaissent pas le verre et peuvent gravement se blesser contre fenêtres ou miroirs.','Birds don''t recognise glass and can seriously injure themselves on windows or mirrors.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Kanarie','Canari','Canary','kanarie','kanarie',12,9,'Ontdek de basisbehoeften van een kanarie voor een gezond en gelukkig vogelleven.','Découvrez les besoins essentiels d''un canari pour une vie d''oiseau saine et heureuse.','Discover the basic needs of a canary for a healthy, happy bird life.','vogels',41)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Wat is de minimale kooibreedte voor een kanarie?','Quelle est la largeur minimale de cage pour un canari ?','What is the minimum cage width for a canary?','["20 cm", "60-80 cm", "10 cm", "Breedte doet er niet toe"]'::jsonb,'["20 cm", "60-80 cm", "10 cm", "La largeur n''a pas d''importance"]'::jsonb,'["20 cm", "60-80 cm", "10 cm", "Width doesn''t matter"]'::jsonb,1,'Kanaries vliegen liever horizontaal dan verticaal, dus een brede kooi is belangrijker dan een hoge.','Les canaris préfèrent voler horizontalement plutôt que verticalement, une cage large est donc plus importante qu''une cage haute.','Canaries prefer flying horizontally rather than vertically, so a wide cage matters more than a tall one.'),
  (1,'tekst','Waarom is directe tocht gevaarlijk voor een kanarie?','Pourquoi les courants d''air directs sont-ils dangereux pour un canari ?','Why are direct drafts dangerous for a canary?','["Ze houden ervan", "Kan longontsteking veroorzaken", "Het maakt hen sterker", "Er is geen gevaar"]'::jsonb,'["Ils adorent ça", "Peut provoquer une pneumonie", "Cela les rend plus forts", "Il n''y a aucun danger"]'::jsonb,'["They love it", "Can cause pneumonia", "It makes them stronger", "There is no danger"]'::jsonb,1,'Kanaries zijn gevoelig voor koude tocht, wat luchtweginfecties kan veroorzaken.','Les canaris sont sensibles aux courants d''air froid, ce qui peut causer des infections respiratoires.','Canaries are sensitive to cold drafts, which can cause respiratory infections.'),
  (1,'tekst','Welke temperatuur verdraagt een kanarie het best?','Quelle température un canari supporte-t-il le mieux ?','What temperature does a canary tolerate best?','["5-10°C", "18-22°C", "30-35°C", "Temperatuur maakt niet uit"]'::jsonb,'["5-10°C", "18-22°C", "30-35°C", "La température n''a pas d''importance"]'::jsonb,'["5-10°C", "18-22°C", "30-35°C", "Temperature doesn''t matter"]'::jsonb,1,'Een stabiele kamertemperatuur tussen 18 en 22°C zonder plotselinge schommelingen is ideaal.','Une température ambiante stable entre 18 et 22°C sans variations brusques est idéale.','A stable room temperature between 18 and 22°C without sudden swings is ideal.'),
  (1,'tekst','Wat is een goede locatie voor een kanariekooi in huis?','Quel est un bon emplacement pour une cage à canari à la maison ?','What is a good location for a canary cage at home?','["Direct in fel zonlicht zonder schaduw", "Rustige plek met deels natuurlijk licht en geen tocht", "In de badkamer bij stoom", "Naast de luidsprekers"]'::jsonb,'["En plein soleil sans ombre", "Endroit calme avec lumière naturelle partielle et sans courant d''air", "Dans la salle de bain avec vapeur", "À côté des enceintes"]'::jsonb,'["Direct in harsh sunlight with no shade", "Quiet spot with some natural light and no draft", "In the bathroom with steam", "Next to the speakers"]'::jsonb,1,'Een rustige, tochtvrije plek met wisselend licht en donker helpt het natuurlijke ritme te behouden.','Un endroit calme, sans courant d''air, avec alternance de lumière aide à préserver le rythme naturel.','A quiet, draft-free spot with alternating light helps maintain a natural rhythm.'),
  (2,'tekst','Waaruit bestaat een uitgebalanceerd dieet voor een kanarie?','En quoi consiste une alimentation équilibrée pour un canari ?','What does a balanced diet for a canary consist of?','["Enkel zaadmengeling", "Zaadmengeling aangevuld met groenten en fruit", "Enkel brood", "Enkel water en zaad zonder groenten"]'::jsonb,'["Uniquement un mélange de graines", "Mélange de graines complété de légumes et fruits", "Uniquement du pain", "Uniquement eau et graines sans légumes"]'::jsonb,'["Seed mix only", "Seed mix supplemented with vegetables and fruit", "Bread only", "Only water and seed, no vegetables"]'::jsonb,1,'Verse groenten en fruit leveren vitamines die in een puur zaaddieet ontbreken.','Les légumes et fruits frais apportent des vitamines absentes d''une alimentation exclusivement à base de graines.','Fresh vegetables and fruit provide vitamins missing from a pure seed diet.'),
  (2,'tekst','Wat mag je een kanarie nooit geven?','Que ne faut-il jamais donner à un canari ?','What should you never give a canary?','["Sla", "Chocolade", "Appel", "Wortel"]'::jsonb,'["De la laitue", "Du chocolat", "Une pomme", "Une carotte"]'::jsonb,'["Lettuce", "Chocolate", "Apple", "Carrot"]'::jsonb,1,'Chocolade bevat theobromine, giftig voor vogels en kan hartfalen veroorzaken.','Le chocolat contient de la théobromine, toxique pour les oiseaux et pouvant causer une insuffisance cardiaque.','Chocolate contains theobromine, toxic to birds and can cause heart failure.'),
  (2,'tekst','Waarom heeft een kanarie grit of kalk nodig?','Pourquoi un canari a-t-il besoin de grit ou de calcium ?','Why does a canary need grit or calcium?','["Voor de smaak", "Voor spijsvertering en botgezondheid, vooral bij leggende vrouwtjes", "Het is niet nodig", "Om te spelen"]'::jsonb,'["Pour le goût", "Pour la digestion et la santé osseuse, surtout chez les femelles pondeuses", "Ce n''est pas nécessaire", "Pour jouer"]'::jsonb,'["For taste", "For digestion and bone health, especially in laying females", "It''s not necessary", "To play"]'::jsonb,1,'Kalk ondersteunt eierproductie en botsterkte, grit helpt bij het verteren van zaden.','Le calcium soutient la production d''œufs et la solidité osseuse, le grit aide à digérer les graines.','Calcium supports egg production and bone strength; grit helps digest seeds.'),
  (2,'tekst','Hoe merk je dat een kanarie mogelijk ziek is?','Comment remarque-t-on qu''un canari est peut-être malade ?','How can you tell a canary might be sick?','["Hij zingt de hele dag", "Verminderde zang, opgezette veren, zit stil op de bodem", "Hij eet normaal", "Hij baadt elke dag"]'::jsonb,'["Il chante toute la journée", "Chant réduit, plumes ébouriffées, reste immobile au sol", "Il mange normalement", "Il se baigne chaque jour"]'::jsonb,'["It sings all day", "Reduced singing, fluffed feathers, sitting still at the bottom", "It eats normally", "It bathes daily"]'::jsonb,1,'Minder zingen en stil op de bodem zitten zijn vaak vroege tekenen van ziekte.','Chanter moins et rester immobile au sol sont souvent des signes précoces de maladie.','Singing less and sitting still on the cage floor are often early signs of illness.'),
  (3,'tekst','Waarom zingen mannetjeskanaries meer dan vrouwtjes?','Pourquoi les canaris mâles chantent-ils plus que les femelles ?','Why do male canaries sing more than females?','["Toeval", "Territoriaal en baltsgedrag", "Ze zijn banger", "Ze zijn zieker"]'::jsonb,'["Le hasard", "Comportement territorial et de parade nuptiale", "Ils ont plus peur", "Ils sont plus malades"]'::jsonb,'["Coincidence", "Territorial and courtship behaviour", "They are more scared", "They are sicker"]'::jsonb,1,'Zang bij mannetjes dient om territorium af te bakenen en vrouwtjes aan te trekken.','Le chant des mâles sert à délimiter le territoire et attirer les femelles.','Male song serves to mark territory and attract females.'),
  (3,'tekst','Kunnen twee mannelijke kanaries best samen in één kooi leven?','Deux canaris mâles peuvent-ils bien vivre ensemble dans une seule cage ?','Can two male canaries live well together in one cage?','["Ja, altijd probleemloos", "Vaak niet, ze kunnen territoriaal vechten", "Enkel als ze familie zijn", "Kanaries leven nooit samen"]'::jsonb,'["Oui, toujours sans problème", "Souvent pas, ils peuvent se battre pour le territoire", "Seulement s''ils sont de la même famille", "Les canaris ne vivent jamais ensemble"]'::jsonb,'["Yes, always without issue", "Often not, they may fight over territory", "Only if they''re related", "Canaries never live together"]'::jsonb,1,'Mannelijke kanaries zijn vaak territoriaal en kunnen elkaar verwonden in een gedeelde kooi.','Les canaris mâles sont souvent territoriaux et peuvent se blesser dans une cage partagée.','Male canaries are often territorial and can injure each other in a shared cage.'),
  (3,'tekst','Hoe reageert een kanarie meestal op hanteren met de hand?','Comment un canari réagit-il généralement à la manipulation manuelle ?','How does a canary typically react to hand-handling?','["Ze houden er erg van", "Ze vinden dit meestal stresserend, in tegenstelling tot parkieten", "Ze zoeken het zelf op", "Het maakt hen niets uit"]'::jsonb,'["Ils adorent ça", "Ils trouvent cela généralement stressant, contrairement aux perruches", "Ils le recherchent eux-mêmes", "Cela leur est indifférent"]'::jsonb,'["They love it very much", "They usually find it stressful, unlike budgies", "They seek it out themselves", "They don''t mind at all"]'::jsonb,1,'Kanaries zijn doorgaans kijkvogels; ze worden best niet gedwongen om vastgehouden te worden.','Les canaris sont généralement des oiseaux d''observation ; il vaut mieux ne pas les forcer à être manipulés.','Canaries are generally ''watch'' birds; they shouldn''t be forced to be handled.'),
  (3,'tekst','Wat kan helpen om verveling bij een kanarie te voorkomen?','Qu''est-ce qui peut aider à prévenir l''ennui chez un canari ?','What can help prevent boredom in a canary?','["Kooi altijd afgedekt houden", "Speeltjes, takjes en variatie in de omgeving", "Nooit iets veranderen", "De kooi zo klein mogelijk houden"]'::jsonb,'["Garder la cage toujours couverte", "Jouets, branches et variation dans l''environnement", "Ne jamais rien changer", "Garder la cage aussi petite que possible"]'::jsonb,'["Always keeping the cage covered", "Toys, twigs and variation in the environment", "Never changing anything", "Keeping the cage as small as possible"]'::jsonb,1,'Verrijking zoals natuurlijke takjes en afwisseling stimuleert natuurlijk gedrag en voorkomt verveling.','Un enrichissement comme des branches naturelles et de la variété stimule le comportement naturel et évite l''ennui.','Enrichment like natural twigs and variety stimulates natural behaviour and prevents boredom.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Stadshond','Chien en ville','City Dog','stadshond','stadshond',12,9,'Alles wat je moet weten om een hond gelukkig en gezond te houden in de stad.','Tout ce qu''il faut savoir pour garder un chien heureux et en bonne santé en ville.','Everything you need to know to keep a dog happy and healthy in the city.','huisdieren',50)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Hoeveel wandelingen per dag heeft een gemiddelde stadshond minstens nodig?','De combien de promenades par jour un chien en ville a-t-il besoin au minimum ?','How many walks per day does an average city dog need at minimum?','["1 korte wandeling", "Minstens 2-3 wandelingen", "Enkel in het weekend", "Geen, een tuin volstaat"]'::jsonb,'["1 courte promenade", "Au moins 2-3 promenades", "Seulement le week-end", "Aucune, un jardin suffit"]'::jsonb,'["1 short walk", "At least 2-3 walks", "Only on weekends", "None, a garden is enough"]'::jsonb,1,'Stadshonden zonder tuin hebben meerdere wandelingen per dag nodig voor beweging en behoeftes doen.','Les chiens en ville sans jardin ont besoin de plusieurs sorties par jour pour bouger et faire leurs besoins.','City dogs without a garden need multiple walks a day for exercise and toileting.'),
  (1,'tekst','Waarom kan het asfalt in de zomer gevaarlijk zijn voor een hond?','Pourquoi l''asphalte peut-il être dangereux pour un chien en été ?','Why can asphalt be dangerous for a dog in summer?','["Het is te zacht", "Het kan gloeiend heet worden en pootjes verbranden", "Honden houden er niet van", "Er is geen gevaar"]'::jsonb,'["C''est trop mou", "Il peut devenir brûlant et brûler les coussinets", "Les chiens n''aiment pas ça", "Il n''y a aucun danger"]'::jsonb,'["It''s too soft", "It can become scorching hot and burn paws", "Dogs just dislike it", "There is no danger"]'::jsonb,1,'Test de temperatuur met je hand: als het te heet is voor jou, is het te heet voor de pootjes.','Testez la température avec votre main : si c''est trop chaud pour vous, c''est trop chaud pour les coussinets.','Test the temperature with your hand: if it''s too hot for you, it''s too hot for paws.'),
  (1,'tekst','Hoe kan je stadslawaai en drukte het best introduceren bij een jonge hond?','Comment introduire au mieux le bruit et l''agitation urbaine chez un jeune chien ?','How should you best introduce city noise and bustle to a young dog?','["Direct blootstellen aan drukke pleinen", "Geleidelijk en positief, stap voor stap", "Nooit buiten komen", "Enkel ''s nachts wandelen"]'::jsonb,'["L''exposer directement aux places animées", "Progressivement et positivement, étape par étape", "Ne jamais sortir", "Sortir uniquement la nuit"]'::jsonb,'["Direct exposure to busy squares", "Gradually and positively, step by step", "Never go outside", "Only walk at night"]'::jsonb,1,'Geleidelijke, positieve socialisatie voorkomt angst en overprikkeling door verkeer, mensen en geluiden.','Une socialisation progressive et positive évite la peur et la surstimulation dues au trafic, aux gens et aux bruits.','Gradual, positive socialisation prevents fear and overstimulation from traffic, people and noise.'),
  (1,'tekst','Wat is belangrijk bij het kiezen van een woning voor een hond in de stad?','Qu''est-ce qui est important lors du choix d''un logement pour un chien en ville ?','What matters when choosing housing for a dog in the city?','["Enkel de grootte van de woonkamer", "Toegang tot buitenruimte of nabijgelegen parken", "De kleur van de gordijnen", "Het aantal verdiepingen"]'::jsonb,'["Uniquement la taille du salon", "Accès à un espace extérieur ou des parcs proches", "La couleur des rideaux", "Le nombre d''étages"]'::jsonb,'["Only the size of the living room", "Access to outdoor space or nearby parks", "The colour of the curtains", "The number of floors"]'::jsonb,1,'Toegang tot groene ruimte in de buurt is essentieel voor de mentale en fysieke gezondheid van een hond.','L''accès à des espaces verts à proximité est essentiel pour la santé mentale et physique d''un chien.','Access to nearby green space is essential for a dog''s mental and physical health.'),
  (2,'tekst','Hoeveel keer per dag krijgt een volwassen hond doorgaans te eten?','Combien de fois par jour un chien adulte doit-il généralement manger ?','How many times a day does an adult dog usually eat?','["1-2 keer", "5-6 keer", "Enkel om de twee dagen", "Ononderbroken vrije toegang"]'::jsonb,'["1-2 fois", "5-6 fois", "Seulement tous les deux jours", "Accès libre en continu"]'::jsonb,'["1-2 times", "5-6 times", "Only every other day", "Continuous free access"]'::jsonb,0,'De meeste volwassen honden hebben genoeg aan 1 tot 2 gestructureerde maaltijden per dag.','La plupart des chiens adultes se contentent d''1 à 2 repas structurés par jour.','Most adult dogs do well with 1 to 2 structured meals a day.'),
  (2,'tekst','Wat is een risico van te weinig lichaamsbeweging bij een stadshond?','Quel est un risque lié à un manque d''exercice chez un chien en ville ?','What is a risk of too little exercise for a city dog?','["Betere spijsvertering", "Overgewicht en gedragsproblemen zoals destructief gedrag", "Meer energie", "Geen enkel risico"]'::jsonb,'["Meilleure digestion", "Surpoids et troubles du comportement comme la destruction", "Plus d''énergie", "Aucun risque"]'::jsonb,'["Better digestion", "Obesity and behaviour problems like destructiveness", "More energy", "No risk at all"]'::jsonb,1,'Onvoldoende beweging leidt vaak tot overgewicht en opgekropte energie die zich uit in destructief gedrag.','Un manque d''exercice mène souvent au surpoids et à une énergie accumulée qui se traduit par des comportements destructeurs.','Insufficient exercise often leads to obesity and pent-up energy expressed as destructive behaviour.'),
  (2,'tekst','Waarom is het belangrijk om drinkwater mee te nemen tijdens warme wandelingen?','Pourquoi est-il important d''emporter de l''eau lors des promenades par temps chaud ?','Why is it important to bring drinking water on hot walks?','["Om zelf te drinken", "Om oververhitting en uitdroging bij de hond te voorkomen", "Water is niet nodig buiten", "Om de hond nat te maken voor de lol"]'::jsonb,'["Pour boire soi-même", "Pour éviter la surchauffe et la déshydratation du chien", "L''eau n''est pas nécessaire dehors", "Pour mouiller le chien pour s''amuser"]'::jsonb,'["To drink yourself", "To prevent overheating and dehydration in the dog", "Water isn''t needed outside", "To wet the dog for fun"]'::jsonb,1,'Honden koelen af door hijgen; zonder voldoende water lopen ze risico op hitteberoerte.','Les chiens se refroidissent en haletant ; sans eau suffisante, ils risquent un coup de chaleur.','Dogs cool down by panting; without enough water they risk heatstroke.'),
  (2,'tekst','Wat kan wijzen op stress of een gezondheidsprobleem bij een hond in een druk stadsklimaat?','Qu''est-ce qui peut indiquer du stress ou un problème de santé chez un chien en milieu urbain animé ?','What can indicate stress or a health problem in a dog in a busy urban environment?','["Normale eetlust", "Overmatig hijgen, verminderde eetlust of overdreven blaffen", "Rustig slapen ''s nachts", "Actief spelen met speeltjes"]'::jsonb,'["Appétit normal", "Halètement excessif, perte d''appétit ou aboiements excessifs", "Dormir calmement la nuit", "Jouer activement avec des jouets"]'::jsonb,'["Normal appetite", "Excessive panting, reduced appetite or excessive barking", "Sleeping calmly at night", "Playing actively with toys"]'::jsonb,1,'Verandering in eetlust of gedrag zijn vaak vroege signalen van stress of onderliggende problemen.','Un changement d''appétit ou de comportement est souvent un signal précoce de stress ou de problème sous-jacent.','Changes in appetite or behaviour are often early signals of stress or underlying issues.'),
  (3,'tekst','Hoe reageert een hond het best op drukke voetgangersgebieden?','Comment un chien devrait-il réagir face aux zones piétonnes animées ?','How should a dog ideally react to busy pedestrian areas?','["Met paniek en trekken aan de lijn", "Rustig en aandachtig naar de begeleider, dankzij training", "Door te blaffen naar iedereen", "Door weg te rennen"]'::jsonb,'["Avec panique et en tirant sur la laisse", "Calmement et attentif au maître, grâce à l''entraînement", "En aboyant sur tout le monde", "En s''enfuyant"]'::jsonb,'["With panic and pulling on the leash", "Calmly and attentive to the handler, thanks to training", "By barking at everyone", "By running away"]'::jsonb,1,'Consistente training en socialisatie helpen een hond kalm blijven te midden van stadsdrukte.','Un entraînement et une socialisation cohérents aident le chien à rester calme au milieu de l''agitation urbaine.','Consistent training and socialisation help a dog stay calm amid city bustle.'),
  (3,'tekst','Waarom is het belangrijk je hond aan een vaste dagroutine te laten wennen in de stad?','Pourquoi est-il important d''habituer son chien à une routine quotidienne fixe en ville ?','Why is it important to accustom your dog to a fixed daily routine in the city?','["Het geeft rust en voorspelbaarheid, wat stress vermindert", "Honden hebben geen routine nodig", "Het maakt geen verschil", "Enkel nuttig voor puppy''s"]'::jsonb,'["Cela apporte calme et prévisibilité, réduisant le stress", "Les chiens n''ont pas besoin de routine", "Cela ne change rien", "Utile seulement pour les chiots"]'::jsonb,'["It gives calm and predictability, reducing stress", "Dogs don''t need routine", "It makes no difference", "Only useful for puppies"]'::jsonb,0,'Een voorspelbare routine met wandelingen en maaltijden geeft honden een gevoel van veiligheid in een drukke omgeving.','Une routine prévisible de promenades et repas donne aux chiens un sentiment de sécurité dans un environnement animé.','A predictable routine of walks and meals gives dogs a sense of security in a busy environment.'),
  (3,'tekst','Wat is een goede manier om overprikkeling te voorkomen na een drukke stadswandeling?','Quelle est une bonne façon d''éviter la surstimulation après une promenade urbaine animée ?','What is a good way to prevent overstimulation after a busy city walk?','["Meteen weer naar buiten gaan", "Een rustmoment thuis geven zonder prikkels", "De hond alleen laten in een lawaaierige ruimte", "Extra speeltijd met andere honden direct erna"]'::jsonb,'["Ressortir immédiatement", "Offrir un moment de repos calme à la maison", "Laisser le chien seul dans un espace bruyant", "Du temps de jeu supplémentaire avec d''autres chiens juste après"]'::jsonb,'["Go straight back outside", "Give a calm rest period at home without stimuli", "Leave the dog alone in a noisy space", "Extra playtime with other dogs right after"]'::jsonb,1,'Rust na prikkelrijke ervaringen helpt het zenuwstelsel van de hond te herstellen en voorkomt oververmoeidheid.','Le repos après des expériences stimulantes aide le système nerveux du chien à récupérer et évite l''épuisement.','Rest after stimulating experiences helps the dog''s nervous system recover and prevents overtiredness.'),
  (3,'tekst','Hoe kan je een stadshond het best socialiseren met andere honden?','Comment socialiser au mieux un chien de ville avec d''autres chiens ?','How can you best socialise a city dog with other dogs?','["Via gecontroleerde, positieve ontmoetingen op eigen tempo", "Door hem los te laten bij elke hond die hij tegenkomt", "Door contact met andere honden te vermijden", "Enkel via videobeelden van honden"]'::jsonb,'["Via des rencontres contrôlées et positives à son rythme", "En le laissant en liberté avec chaque chien croisé", "En évitant tout contact avec d''autres chiens", "Uniquement via des vidéos de chiens"]'::jsonb,'["Through controlled, positive encounters at their own pace", "By letting them loose with every dog they meet", "By avoiding contact with other dogs entirely", "Only through videos of dogs"]'::jsonb,0,'Gecontroleerde, positieve ontmoetingen bouwen vertrouwen op en verminderen angst of agressie tegenover andere honden.','Des rencontres contrôlées et positives instaurent la confiance et réduisent la peur ou l''agressivité envers les autres chiens.','Controlled, positive encounters build confidence and reduce fear or aggression toward other dogs.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Appartementskat','Chat d''appartement','Apartment Cat','appartementskat','appartementskat',12,9,'Tips voor een gelukkig en gezond kattenleven in een appartement zonder buitenruimte.','Conseils pour une vie de chat heureuse et saine en appartement sans espace extérieur.','Tips for a happy, healthy cat''s life in an apartment without outdoor access.','huisdieren',51)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Waarom is verticale ruimte belangrijk voor een appartementskat?','Pourquoi l''espace vertical est-il important pour un chat d''appartement ?','Why is vertical space important for an apartment cat?','["Katten houden niet van hoogte", "Het geeft extra territorium en uitkijkpunten in een beperkte ruimte", "Het is enkel decoratief", "Het is gevaarlijk voor katten"]'::jsonb,'["Les chats n''aiment pas la hauteur", "Cela offre plus de territoire et des points d''observation dans un espace limité", "C''est purement décoratif", "C''est dangereux pour les chats"]'::jsonb,'["Cats dislike height", "It provides extra territory and vantage points in a limited space", "It''s purely decorative", "It''s dangerous for cats"]'::jsonb,1,'Kattenrekken en hoge plekken vergroten het bruikbare territorium in een klein appartement en verminderen stress.','Les arbres à chat et les hauteurs augmentent le territoire utile dans un petit appartement et réduisent le stress.','Cat trees and high perches expand usable territory in a small apartment and reduce stress.'),
  (1,'tekst','Hoeveel kattenbakken worden aanbevolen voor één kat in een appartement?','Combien de bacs à litière sont recommandés pour un chat en appartement ?','How many litter boxes are recommended for one cat in an apartment?','["0, buiten volstaat", "Minstens 2 (aantal katten + 1)", "Enkel 1 is altijd genoeg", "5 of meer, altijd"]'::jsonb,'["0, l''extérieur suffit", "Au moins 2 (nombre de chats + 1)", "1 seul suffit toujours", "5 ou plus, systématiquement"]'::jsonb,'["0, outside is enough", "At least 2 (number of cats + 1)", "Just 1 is always enough", "5 or more, always"]'::jsonb,1,'De vuistregel is aantal katten plus één bak, verspreid op verschillende plekken, om conflicten en vervuiling te vermijden.','La règle est nombre de chats plus un bac, répartis à différents endroits, pour éviter conflits et saleté.','The rule of thumb is number of cats plus one box, spread around, to avoid conflict and mess.'),
  (1,'tekst','Wat is een belangrijk gevaar voor katten in appartementen op hogere verdiepingen?','Quel est un danger important pour les chats dans les appartements en étage ?','What is an important danger for cats in apartments on higher floors?','["Vallen door onbeveiligde ramen (high-rise syndroom)", "Te veel zonlicht", "Te weinig geluid", "Te koude vloeren"]'::jsonb,'["Chute par des fenêtres non sécurisées (syndrome du gratte-ciel)", "Trop de lumière du soleil", "Trop peu de bruit", "Sols trop froids"]'::jsonb,'["Falling through unsecured windows (high-rise syndrome)", "Too much sunlight", "Too little noise", "Cold floors"]'::jsonb,0,'Katten kunnen door open ramen vallen bij het jagen op vogels of insecten; horren zijn essentieel.','Les chats peuvent tomber par des fenêtres ouvertes en chassant oiseaux ou insectes ; des moustiquaires sont essentielles.','Cats can fall through open windows while chasing birds or insects; screens are essential.'),
  (1,'tekst','Waarom is krabmateriaal essentieel in een appartement zonder buitenruimte?','Pourquoi le matériel à griffer est-il essentiel dans un appartement sans espace extérieur ?','Why is scratching material essential in an apartment without outdoor access?','["Om het meubilair te sparen en natuurlijk gedrag te uiten", "Enkel om nagels te verwijderen", "Het is niet nodig binnenshuis", "Om de kat te straffen"]'::jsonb,'["Pour préserver les meubles et exprimer un comportement naturel", "Uniquement pour enlever les griffes", "Ce n''est pas nécessaire en intérieur", "Pour punir le chat"]'::jsonb,'["To spare furniture and express natural behaviour", "Only to remove nails", "It''s not needed indoors", "To punish the cat"]'::jsonb,0,'Krabben is een natuurlijke behoefte om klauwen te onderhouden en territorium te markeren.','Griffer est un besoin naturel pour entretenir les griffes et marquer le territoire.','Scratching is a natural need to maintain claws and mark territory.'),
  (2,'tekst','Hoe vaak per dag eet een volwassen kat idealiter?','Combien de fois par jour un chat adulte doit-il idéalement manger ?','How many times a day should an adult cat ideally eat?','["1 grote maaltijd", "2-4 kleinere maaltijden", "Continu onbeperkt droogvoer zonder controle", "Om de twee dagen"]'::jsonb,'["1 gros repas", "2 à 4 petits repas", "Croquettes en libre-service constant sans contrôle", "Tous les deux jours"]'::jsonb,'["1 large meal", "2-4 smaller meals", "Constant unlimited dry food with no control", "Every other day"]'::jsonb,1,'Meerdere kleine maaltijden bootsen het natuurlijke jachtpatroon van katten na en helpen overgewicht voorkomen.','Plusieurs petits repas imitent le schéma de chasse naturel du chat et aident à prévenir le surpoids.','Multiple small meals mimic a cat''s natural hunting pattern and help prevent obesity.'),
  (2,'tekst','Wat is een risico van een te sedentaire levensstijl bij een binnenkat?','Quel est un risque d''un mode de vie trop sédentaire chez un chat d''intérieur ?','What is a risk of a too sedentary lifestyle for an indoor cat?','["Betere spijsvertering", "Overgewicht en gewrichtsproblemen", "Langer leven zonder gevolgen", "Meer energie"]'::jsonb,'["Meilleure digestion", "Surpoids et problèmes articulaires", "Vie plus longue sans conséquences", "Plus d''énergie"]'::jsonb,'["Better digestion", "Obesity and joint problems", "Longer life with no consequences", "More energy"]'::jsonb,1,'Weinig beweging binnenshuis kan leiden tot overgewicht, wat gewrichten en algemene gezondheid belast.','Le manque d''exercice en intérieur peut mener au surpoids, ce qui pèse sur les articulations et la santé générale.','Little indoor exercise can lead to obesity, straining joints and overall health.'),
  (2,'tekst','Welk voedsel is giftig voor katten?','Quel aliment est toxique pour les chats ?','Which food is toxic to cats?','["Gekookte kip", "Ui en look", "Kattengras", "Gestoomde vis zonder graten"]'::jsonb,'["Poulet cuit", "Oignon et ail", "Herbe à chat", "Poisson vapeur sans arêtes"]'::jsonb,'["Cooked chicken", "Onion and garlic", "Cat grass", "Steamed fish without bones"]'::jsonb,1,'Ui en look bevatten stoffen die rode bloedcellen bij katten kunnen beschadigen en bloedarmoede veroorzaken.','L''oignon et l''ail contiennent des substances pouvant endommager les globules rouges des chats et causer de l''anémie.','Onion and garlic contain substances that can damage cats'' red blood cells and cause anaemia.'),
  (2,'tekst','Wat kan wijzen op stress of ziekte bij een binnenkat?','Qu''est-ce qui peut indiquer du stress ou une maladie chez un chat d''intérieur ?','What can indicate stress or illness in an indoor cat?','["Normaal speelgedrag", "Buiten de kattenbak plassen of overmatig poetsen", "Regelmatig eten", "Rustig slapen"]'::jsonb,'["Comportement de jeu normal", "Uriner hors du bac ou toilettage excessif", "Manger régulièrement", "Dormir calmement"]'::jsonb,'["Normal play behaviour", "Urinating outside the litter box or excessive grooming", "Eating regularly", "Sleeping calmly"]'::jsonb,1,'Onzindelijkheid en overmatig poetsen zijn vaak signalen van stress, verveling of onderliggende gezondheidsproblemen.','Malpropreté et toilettage excessif sont souvent des signaux de stress, d''ennui ou de problèmes de santé sous-jacents.','House-soiling and excessive grooming are often signals of stress, boredom, or underlying health issues.'),
  (3,'tekst','Hoe kan je natuurlijk jaaggedrag stimuleren bij een appartementskat?','Comment stimuler le comportement de chasse naturel chez un chat d''appartement ?','How can you stimulate natural hunting behaviour in an apartment cat?','["Met interactief speelgoed zoals hengels en puzzelvoeders", "Door de kat de hele dag te laten slapen", "Door nooit te spelen", "Door enkel droogvoer in een bak te geven"]'::jsonb,'["Avec des jouets interactifs comme cannes à pêche et distributeurs à énigmes", "En laissant le chat dormir toute la journée", "En ne jouant jamais", "En donnant uniquement des croquettes dans un bol"]'::jsonb,'["With interactive toys like wand toys and puzzle feeders", "By letting the cat sleep all day", "By never playing", "By only giving dry food in a bowl"]'::jsonb,0,'Interactief spel en puzzelvoeders bootsen jachtgedrag na en houden een binnenkat mentaal gestimuleerd.','Le jeu interactif et les distributeurs à énigmes imitent le comportement de chasse et stimulent mentalement le chat d''intérieur.','Interactive play and puzzle feeders mimic hunting behaviour and keep an indoor cat mentally stimulated.'),
  (3,'tekst','Waarom is een vaste, voorspelbare routine belangrijk voor een appartementskat?','Pourquoi une routine fixe et prévisible est-elle importante pour un chat d''appartement ?','Why is a fixed, predictable routine important for an apartment cat?','["Het vermindert stress door voorspelbaarheid van voeding en spel", "Katten hebben geen routine nodig", "Het maakt geen verschil voor katten", "Enkel belangrijk voor kittens"]'::jsonb,'["Cela réduit le stress grâce à la prévisibilité des repas et du jeu", "Les chats n''ont pas besoin de routine", "Cela ne change rien pour les chats", "Important uniquement pour les chatons"]'::jsonb,'["It reduces stress through predictability of feeding and play", "Cats don''t need routine", "It makes no difference for cats", "Only important for kittens"]'::jsonb,0,'Katten zijn gevoelig voor verandering; een vaste routine van eten en spelen geeft veiligheid en rust.','Les chats sont sensibles au changement ; une routine fixe de repas et de jeu apporte sécurité et calme.','Cats are sensitive to change; a fixed routine of feeding and play provides security and calm.'),
  (3,'tekst','Hoe reageer je het best als je kat verstopt zit tijdens een verhuis of drukte?','Comment réagir au mieux si votre chat se cache pendant un déménagement ou une agitation ?','How should you best react if your cat hides during a move or busy period?','["De kat forceren om te voorschijn te komen", "Rust en tijd geven, met toegang tot een veilige plek", "De kat straffen", "De kat negeren volledig zonder controle"]'::jsonb,'["Forcer le chat à sortir", "Lui laisser calme et temps, avec accès à un endroit sûr", "Punir le chat", "L''ignorer complètement sans surveillance"]'::jsonb,'["Force the cat to come out", "Give calm and time, with access to a safe spot", "Punish the cat", "Ignore it entirely with no check-ins"]'::jsonb,1,'Katten hebben nood aan een veilige schuilplaats om stress te verwerken; geduld herstelt vertrouwen sneller.','Les chats ont besoin d''une cachette sûre pour gérer le stress ; la patience restaure la confiance plus vite.','Cats need a safe hiding spot to process stress; patience restores trust faster.'),
  (3,'tekst','Waarom is het aanbieden van meerdere rustplekken belangrijk in een appartement met meerdere katten?','Pourquoi est-il important d''offrir plusieurs lieux de repos dans un appartement avec plusieurs chats ?','Why is offering multiple resting spots important in an apartment with multiple cats?','["Om conflicten en concurrentie om ruimte te verminderen", "Katten delen graag altijd dezelfde plek", "Het heeft geen invloed op hun gedrag", "Om de kat te straffen"]'::jsonb,'["Pour réduire les conflits et la compétition pour l''espace", "Les chats aiment toujours partager le même endroit", "Cela n''a aucune influence sur leur comportement", "Pour punir le chat"]'::jsonb,'["To reduce conflict and competition for space", "Cats always love sharing the same spot", "It has no effect on their behaviour", "To punish the cat"]'::jsonb,0,'Elke kat heeft eigen territorium nodig; voldoende rustplekken vermijden spanning tussen kattenn in huis.','Chaque chat a besoin de son propre territoire ; suffisamment de lieux de repos évitent les tensions entre chats.','Each cat needs its own territory; enough resting spots avoid tension between cats in the home.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);
